// Item #933 — the `prod-apk` release build's Gradle heap and its step timeout, pinned.
//
// cd-deploy run 6766 OOMed in :app:compressReleaseAssets at the Expo template's -Xmx2048m (the host
// had 40 GB free), Gradle never exited, and the job sat to its 60-min `timeout-minutes` — which kills
// the job before `Publish failure digest` runs, so no evidence bundle was published. Run 6332 did the
// same on 2026-10-31.
//
// The heap is set in the USER-level gradle.properties from the workflow step, because `android/` is
// regenerated by `expo prebuild --clean` and any edit to the project's gradle.properties is discarded.
// Each assertion below names the regression it catches.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse as parseYaml } from 'yaml';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const workflow = parseYaml(readFileSync(resolve(REPO_ROOT, '.forgejo/workflows/cd-deploy.yml'), 'utf8'));
const job = workflow?.jobs?.['prod-apk'];

const buildStep = () => {
  const steps = (job?.steps ?? []).filter(
    (s) => typeof s.run === 'string' && s.run.includes('mcm-app:build-apk'),
  );
  assert.equal(steps.length, 1, 'expected exactly one prod-apk step that runs mcm-app:build-apk');
  return steps[0];
};

/** The org.gradle.jvmargs value the step writes, or null. */
const jvmargs = (run) => run.match(/org\.gradle\.jvmargs=([^'"\n]+)/)?.[1] ?? null;

/** -Xmx<value> in bytes, for a comparison that does not depend on the unit chosen. */
const xmxBytes = (args) => {
  const m = args.match(/-Xmx(\d+)([kKmMgG]?)/);
  if (!m) return null;
  const mult = { '': 1, k: 1024, m: 1024 ** 2, g: 1024 ** 3 }[m[2].toLowerCase()];
  return Number(m[1]) * mult;
};

test('the release build writes an explicit Gradle heap to the USER-level gradle.properties', () => {
  const run = buildStep().run;
  // The project-level file is regenerated by prebuild; only the user-level file survives it.
  assert.match(run, /\$\{GRADLE_USER_HOME:-\$HOME\/\.gradle\}\/gradle\.properties/);
  const args = jvmargs(run);
  assert.ok(args, 'no org.gradle.jvmargs line in the build step');
  // The Expo template is -Xmx2048m and is what OOMed; anything at or below it is the regression.
  assert.ok(xmxBytes(args) > 2048 * 1024 ** 2, `heap must exceed the 2 GB template default, got: ${args}`);
});

test('a JVM OOM terminates the build instead of hanging it', () => {
  assert.match(jvmargs(buildStep().run) ?? '', /-XX:\+ExitOnOutOfMemoryError/);
});

test('the heap is written BEFORE the build runs', () => {
  const run = buildStep().run;
  const heapAt = run.indexOf('org.gradle.jvmargs');
  // >= 0 first: a missing line is -1, which would otherwise read as "before".
  assert.ok(heapAt >= 0 && heapAt < run.indexOf('mcm-app:build-apk'));
});

test('the build step times out before the job does, so the failure digest still runs', () => {
  const step = buildStep();
  assert.equal(typeof step['timeout-minutes'], 'number', 'build step needs its own timeout-minutes');
  assert.equal(typeof job['timeout-minutes'], 'number');
  // At least 10 minutes of headroom for upload/digest steps after a step timeout.
  assert.ok(
    step['timeout-minutes'] <= job['timeout-minutes'] - 10,
    `step ${step['timeout-minutes']} vs job ${job['timeout-minutes']}`,
  );
  const digest = (job.steps ?? []).find((s) => s.name === 'Publish failure digest');
  assert.ok(digest, 'prod-apk lost its Publish failure digest step');
  assert.match(String(digest.if ?? ''), /always\(\)/);
});

// ─── Feature 087 (FR-019, US4 scenario 5) — the PR-time release build gets the same heap ───────────────
//
// `app-ci`'s app-e2e job builds the same release APK (for the emulator) and had no heap line at all, so
// it ran at the template's -Xmx2048m that OOMed run 6766. PR C's SDK 58 build is its first proof on that
// path, so it carries #933's block too, with the same floor and the same fail-fast flag.

const appCi = parseYaml(readFileSync(resolve(REPO_ROOT, '.forgejo/workflows/app-ci.yml'), 'utf8'));

const appE2eBuildStep = () => {
  const steps = (appCi?.jobs?.['app-e2e']?.steps ?? []).filter(
    (s) => typeof s.run === 'string' && s.run.includes('mcm-app:build-apk'),
  );
  assert.equal(steps.length, 1, 'expected exactly one app-e2e step that runs mcm-app:build-apk');
  return steps[0];
};

test('(087) app-e2e writes the same explicit Gradle heap to the USER-level gradle.properties', () => {
  const run = appE2eBuildStep().run;
  assert.match(run, /\$\{GRADLE_USER_HOME:-\$HOME\/\.gradle\}\/gradle\.properties/);
  const args = jvmargs(run);
  assert.ok(args, "app-e2e's build step sets no org.gradle.jvmargs — it builds at the template's -Xmx2048m");
  assert.equal(xmxBytes(args), xmxBytes(jvmargs(buildStep().run)), `app-e2e and prod-apk heaps differ: ${args}`);
});

test('(087) a JVM OOM terminates the app-e2e build instead of hanging it', () => {
  assert.match(jvmargs(appE2eBuildStep().run) ?? '', /-XX:\+ExitOnOutOfMemoryError/);
});

test('(087) app-e2e writes the heap BEFORE its build runs', () => {
  const run = appE2eBuildStep().run;
  const heapAt = run.indexOf('org.gradle.jvmargs');
  assert.ok(heapAt >= 0 && heapAt < run.indexOf('mcm-app:build-apk'));
});
